INSERT INTO misha.questions (id, location_id, opportunity_id, message_id, question_text, quote, quoted_at, rep_reply, rep_reply_message_id, was_answered, deal_status, client_type, created_at, created_by) VALUES
('1', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'RF1KDvXTuBG1PhBrsfXM', 'does floor track compatibility matter with existing concrete', 'Just looking at the quote! It says flush floor track… mine has to be on top of the existing concrete bit I think! Does that make any difference?', '2026-08-21 12:48:50.431+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('2', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'ARtQB5SpQNApxwhKVbz3', 'can handles be matched to paint colour', 'In terms of the handles… is there no way they can be matched to the paint?', '2026-08-25 12:36:08.14+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('3', 'kHcvavc8fEeqkEPTK2T8', 'eJXcTuYwiNK9JR56rF2d', 'Km4qSTh7YE8NjR22ylbY', 'is an earlier survey slot available', 'Chris with due respect that is less than 24 hours and now a 2 week wait. Is there not an earlier survey?', '2026-06-19 14:23:49.487+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('4', 'IFcSg4YvuVlx56msjbdf', 'jGSGZ7Z0mCFEKtbG8R3L', 'LvorGF477YA3s39RjCad', 'can I pay by credit card instead of bank transfer', 'Any chance I can pay this by credit card vs bank transfer please?', '2026-08-19 07:48:49+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('5', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'd3ctMUqbC3XRDNSVqLNj', 'can I see a real life example of the colour, not just the brochure', 'Do you have any real life examples of the colour I''ve gone for?! It''s kind of hard to tell from the brochure', '2026-08-25 13:00:30.782+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('6', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'yndXO61vwBXGm1dm5Yru', 'can the contract include a refund clause if machinery is needed', 'In terms of the sales contract… could it be included that if we cannot make it work without machinery then I will be refunded the deposit?', '2026-08-25 12:58:00.22+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('7', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', '0YcTpO7WSketAPp2YQoa', 'what is the total cost including any extras', 'Is there anyway someone could come and look and assess actually what the total cost would be with any extras needed?', '2026-08-19 16:59:59.676+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('8', 'kHcvavc8fEeqkEPTK2T8', 'eJXcTuYwiNK9JR56rF2d', 'fz5TIUkyTbHdwpBGoLOz', 'is the extra cost for two colours an industry standard charge, is there flex', 'Ok I''m just doing a final price check on the additional cost for two colours on the windows. Our last builds didn''t charge this and our architect wasn''t sure if that was an industry standard thing. Is there any flex on that?', '2026-06-19 16:05:35.219+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('9', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', '9Nai2MlMMAJ31iRpsT41', 'can trickle vents be included in the window price', 'my dad just gave me some (unsolicited) advice and said that trickle vents are mandatory… so could these be included in the window price?', '2026-08-19 17:19:07.651+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('10', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'DoCYh3kP0NrjFNdtXPM7', 'when is the remaining balance paid after deposit', '40% deposit and then the rest is paid when?', '2026-08-21 11:28:13.704+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('11', 'IFcSg4YvuVlx56msjbdf', 'K0INBScjVtzko6Ehhh2N', 'ZPHC5rp3dsRrFAK0hTEO', 'is it normal to have a handle on only one door', 'I think the door needs to open into what is our living room as otherwise it will block the stairs. Is it normal to only have a handle on one door?', '2026-08-27 07:56:12.895+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('12', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'SGWIk1Kb7Aiizz7AkU8I', 'can we go for a different manufacturer/system than quoted', 'I would really love to go for Cortizo and wondered if that would be possible?', '2026-08-18 14:02:10.849+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:07:18.394548+00', 'misha'),
('25', 'IFcSg4YvuVlx56msjbdf', 'Hkad9qfhaCHyXMa8AgDZ', 'QGzQbhjBXBAMhl660uRZ', 'do you have examples of the cor vision doors on site to view', 'On a separate note, do you guys have any examples of the cor vision doors on site for us to come down and have a look?', '2026-08-17 11:47:28+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('26', 'IFcSg4YvuVlx56msjbdf', 'MPPhGrMMy03uZT1v7JBE', '9E6KGZNIKZ2PCeoTQMHh', 'can you quote for like-for-like replacement as an option too', 'We spoke on the phone about replacing like for like as an option - would you be able to quote on this as well please?', '2026-08-25 12:24:41.001+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('27', 'IFcSg4YvuVlx56msjbdf', 'MPPhGrMMy03uZT1v7JBE', 'kgiD25xDppE2hUzCqZTN', 'does the quote include installation (cherry picker/scaffolding)', 'Would this quote include the installation (cherry picker/scaffolding we spoke about)?', '2026-08-25 12:29:11.842+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('28', 'IFcSg4YvuVlx56msjbdf', 'MPPhGrMMy03uZT1v7JBE', 'Qm6ICSuuewTjG2WTTNlx', 'do you offer aluminium in a sash-window style, and can it fit an existing wifi cable route', 'Do you do any aluminium ones that are the same style as a sash window? So they slide up and down rather than opening out? Also, we currently have the wifi cable going into the room through one of the windows. Would this still be possible with the aluminium design?', '2026-08-28 00:53:27.293+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('29', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'SbC1QWplaKcf0xrJuxmu', 'will the panes fit in the lift', 'But the panes won''t don''t in lift will they?', '2026-08-21 14:07:57.747+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('30', 'IFcSg4YvuVlx56msjbdf', 'PlSluvjcPPaDdR2e8eHx', 'TwIhoEcXrwSd9WGEVDdl', 'can you send the email outlining the refund if machinery is needed', 'In terms of the contract, please could you send the email outlining about the refund if machinery is needed?', '2026-08-27 13:43:18.276+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('31', 'kHcvavc8fEeqkEPTK2T8', 'dU2w6tJQj41hJS0Kwy8A', 'HQlB4Zp5A5syPrZ19ehO', 'do you have a picture of the track', 'Do you have a picture of the track?', '2026-08-12 18:23:21.498+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('32', 'kHcvavc8fEeqkEPTK2T8', 'J5dezFNbXhcjd7Qsj3j7', 'wHnrVd9H8HrQer1qxMmE', 'will you do a proper measurement or does it need an engineers visit', 'We are interested in going ahead - when you visit will you do a proper measurement or would that still require and engineers visit?', '2026-07-24 15:28:01+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('33', 'kHcvavc8fEeqkEPTK2T8', 'eJXcTuYwiNK9JR56rF2d', 'pP5JE1Hxlk2T03bdncGp', 'can we omit an item from the order and amend the deposit', 'We are going to omit the window/door from the living room (I believe it was 90 x 210cm) from the order if that is ok to amend the deposit this morning', '2026-07-06 08:54:27.045+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('34', 'IFcSg4YvuVlx56msjbdf', 'z9bahUussp8ci1xqcP9R', 'ZJRMEC015d9XdHLvMG0R', 'did the manufacturer send photos with line drawings and measurements', 'Did crittal send you the photos with line drawings with measurements?', '2026-06-15 15:05:21+00', NULL, NULL, NULL, 'abandoned', NULL, '2026-09-18 07:15:44.531925+00', 'misha'),
('35', 'E0nGtwuWd1cmeoc6ilD1', 'JsHs8w5UzW60FMvUHDAL', '2LMDIO4YWBGI6vKaXd3J', 'can you give an idea of spec and cost for a single interior door/side panel', 'We are looking for a single interior door/single side panel - like one half of the attached image. It is for the entrance between kitchen and garden room. The dimensions are approx 120cm wide by 215cm high. Can you give me some idea of spec and cost please.', '2026-07-25 07:25:37+00', NULL, NULL, NULL, 'abandoned', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('36', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', 'p93bBAZQMY2HJmj9N3nv', 'were the plans forwarded correctly, any other questions welcomed', 'Just spotted you weren''t sent the original email with all the details, will forward now, let me know if any other questions', '2026-08-25 11:41:02+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('37', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', 'wQ5FM5Yri58GmwLPSjry', 'can you share the U values for each component', 'Could you share the U values for each component?', '2026-09-02 00:52:30+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('38', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', '8zNK4mrsACBUgj6h5csk', 'can you share a revised final quote after a dimension correction', 'When doing a final review of quotes we noticed a mistake on our end, the window will be a window seat and therefore ~50cm off the internal ground height. This would make the window ~2m tall to be inline with the crittal doors. Please could you share this final quote?', '2026-09-07 19:42:35+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('39', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', 'ToUXK2X9RchnYoQnWwrC', 'can you advise price based on corrected door dimensions', 'I''ve just spotted the dimensions of the door are slightly off too. This should be 2.4m height by 2.9 width. Please could you advise the price based on this?', '2026-09-08 09:22:17+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('40', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', 'IwNpyRRW37LvjjF5JwxD', 'does the window/door height alignment make sense', 'The window should be around ~2m high by 1.2m wide - this will be a window seat so should be installed at bench height and in line with the top of the door. Does that make sense?', '2026-09-08 09:39:02+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('41', 'IFcSg4YvuVlx56msjbdf', '0RkwquT0wuISMWZpp7ox', 'TwViffL18TfsAyAVOF0H', 'do we need full planning and architects/engineers for the full works quoted', 'we''ve found out this week that if we do the full works that we were quoted, we''ll need to get full planning, and potentially architects and engineers', '2026-07-09 07:34:08+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('42', 'IFcSg4YvuVlx56msjbdf', '12sa8DETdw0M55hFCPhg', 'RLfoMmwY6QwyKfOnulZe', 'does everyone have availability for a coordination meeting on construction drawings', 'As discussed this morning it would be good to arrange a coordination meeting to agree construction drawings for the glass link & curtain walling. Does everyone have availability Wednesday 5th August?', '2026-07-27 15:31:42+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:02.545341+00', 'misha'),
('43', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'Otz7dnifo9AI8aTxheIZ', 'is cortizo very expensive, can we get costs for a variety of budgets', 'is the cortizo very expensive? It would be great to get an idea on costs for a variety of budgets just so we can compare. Do you have any photo examples you could share or a rough idea on costs?', '2026-06-22 12:56:19+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('44', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', '3WbuAFUFJwIsHjguIVTt', 'does the quote include trade discounts, is there a cheaper system available', 'Is this including any trade discounts you may have? Is there a system that might come through even cheaper? Obviously the frameless looks fantastic but we may be able to have mullions if worse comes to worse!', '2026-06-22 14:02:12+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('45', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'u2NyYEJWeSypvjS9eUYj', 'what is the lead time and are there more budget-friendly suggestions', 'what is the lead time for the cortizo product? Do you have any smart suggestions that might be more budget friendly?', '2026-06-24 11:27:52+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('46', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', '2A2xg1ukqI5ssWu5srkY', 'is the quoted price including VAT', 'Is that 12k including VAT?', '2026-06-24 15:06:32+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('47', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'pRpwO8ApkvDZt7bkswyD', 'how does the cheaper alternative differ visually, are there photo examples', 'That new price is much more doable. How exactly would this work? Visually how does this differ? Do you have any photo examples you could share of the finished look?', '2026-06-25 11:12:48+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('48', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'kdyr0BlH7Vj65Fskymi5', 'can we pay in cash', 'Are we able to discuss cash payment too; my partner earns a portion of his wage in cash so it would be a great help.', '2026-06-25 12:43:05+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('49', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'muZnOBCo1gZM1rlrSQDf', 'do you have door sets or window frames with slimmer profiles', 'Do you have any door sets that have slimmer frames? The same for the triangular window, any examples of slim frames for this too?', '2026-06-25 13:08:05+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('50', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'FBkCeQWCzun4T7XkWw4p', 'what sleek/frameless sliding door and window ranges do you offer, and what is the total cost with slimmer frames', 'what do you have in the way of sliding doors - anything very sleek and frameless on offer? Do you have any other very sleek ranges that you can suggest for windows/doors? What would the total cost be with that slimmer frame bifold doors?', '2026-06-26 20:47:39+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('51', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'ynOT9SdWsqgky6Vdfzzq', 'can you draw up a revised quote with slim frames included', 'Could you draw us up a revised quote for the slim frames included?', '2026-06-29 08:37:44+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('52', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'kLYUVtSEeAYHeXm4QTft', 'can we place the order before a price rise, and how does measuring/design work', 'Any chance we can get the order placed before to avoid the price jump? How does it generally work with measuring up and also working with your team on the design look once we''ve got you on board?', '2026-06-29 10:30:35+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('53', 'IFcSg4YvuVlx56msjbdf', '1GyrGfxAY8Oi7TQUayRZ', '4lvWd5sfzRJ6Qe75lvGZ', 'can you advise on remaining door options after discounting Crittall', 'We have mostly discounted the Crittall door options but would love some guidance on the remaining options, which are: Wider opening: 2 panel or 3 panel sliding doors or bifold doors; Narrower opening: fixed sheet of glass or a pivot door', '2026-06-29 13:10:34+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('54', 'IFcSg4YvuVlx56msjbdf', '4ACtsPoAaXXBtEWg0orA', 'SsIOc3h2BWJNx3ADyWkz', 'confirming best contact number before a quote call', 'Thank you for your email, sure it is +447590115050.', '2026-07-14 16:22:15+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('55', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', '176M15DeCmF8URNWPyP0', 'went with another company, price was close (not the deciding factor)', 'We''ve decided to proceed with another company that we have worked with before (ultimately not a price decision as you were only £200 more than them if useful to know).', '2026-09-10 07:08:43+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('56', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', 'wQ5FM5Yri58GmwLPSjry', 'was just the double doors and side screens wanted, or also the large fixed window and shaped glazing', 'was it just the double doors and fixed side screens you were looking for or was it the large fixed window + shaped glazing as well?', '2026-08-25 11:41:02+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('57', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', 'xs4FuF8wnvtue3fwzhWx', 'do you have a preference between genuine Crittall steel and aluminium Crittall-style', 'I have sent across 2 options. 1 for genuine Crittall Steel and 1 for an aluminium crittall style. Do you have a preference between the 2?', '2026-08-28 10:37:50+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('58', 'IFcSg4YvuVlx56msjbdf', '0rA1uPzcwyBUT8TJGGlg', 'IwNpyRRW37LvjjF5JwxD', 'will the fixed screen remain at the original height', 'Will the fixed screen remain at 2000mm H?', '2026-09-08 09:39:02+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:17:50.7508+00', 'misha'),
('59', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', '8OVNKgTTG3uqvh76D1b3', 'can the price come down closer to a stated budget', 'We''d had quotes in before more in the region of 12k so this was slightly more what the client had in mind but I do understand these costs vary on quality and timeframe. Ideally more in the realm of 12k if possible.', '2026-06-24 15:02:57+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:18:21.299143+00', 'misha'),
('60', 'IFcSg4YvuVlx56msjbdf', '5yR1FwIWx0BmNfXcGryU', 'kLYUVtSEeAYHeXm4QTft', 'is there a solution for roof lights, and can you see the example shared', 'I have found a solution to having the roof lights as per the example shared', '2026-06-29 10:30:35+00', NULL, NULL, NULL, 'won', NULL, '2026-09-18 07:18:21.299143+00', 'misha'),
('61', 'IFcSg4YvuVlx56msjbdf', '4ACtsPoAaXXBtEWg0orA', 'SsIOc3h2BWJNx3ADyWkz', 'would you like a chat before a quote is sent to align on scope', 'I have received your details but would be keen to have a chat to discuss further to make sure we are on the same page before sending a quote. Please can you share the best contact number to reach you on?', '2026-07-14 16:22:15+00', NULL, NULL, NULL, 'lost', NULL, '2026-09-18 07:18:21.299143+00', 'misha'),
('62', 'IFcSg4YvuVlx56msjbdf', '2FvpLO5G2k5zj5JvM0Rg', '8bPenJn5KQpMNeVUrQ6A', 'when is the customer available for a call to discuss the enquiry', 'I am available to call between now to 16:00. Please let me know if you are available', '2026-07-22 14:08:04+00', NULL, NULL, NULL, 'abandoned', NULL, '2026-09-18 07:18:21.299143+00', 'misha');


-- ---------- misha.requirements (7 INSERT statements) ----------
INSERT INTO misha.requirements (id, location_id, opportunity_id, message_id, requirement_label, quote, quoted_at, is_objection, is_price_limit, price_limit_amount, rep_reply, rep_reply_message_id, deal_status, stage_at_time, client_type, created_at, created_by) VALUES
